1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	// Base premium for a single item of each type.
58	const UNIT_BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const LOYALTY_YEARS_THRESHOLD = 2;
68	const LOYALTY_DISCOUNT_RATE = 2 / 10;
69	const CURSE_SURCHARGE_RATE = 1 / 2;
70	const HIGH_ENCHANTMENT_THRESHOLD = 5;
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];
76	
77	const countByType = (items: Item[]): Map<string, number> =>
78	  items.reduce(
79	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
80	    new Map<string, number>(),
81	  );
82	
83	// A building block of 3 alike components is offered at a special base premium.
84	const basePremiumForItemGroup = (type: string, count: number): number =>
85	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  [...countByType(items)].reduce(
89	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
90	    0,
91	  );
92	
93	const isHighlyEnchanted = (item: Item): boolean =>
94	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
95	
96	const surchargeRate = (item: Item): number =>
97	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
98	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
99	
100	// Item-specific modifiers apply to the affected item's own base premium, i.e.
101	// the unit price of its type — a block discount never shrinks a surcharge.
102	const itemSurcharge = (item: Item): number =>
103	  unitBasePremium(item.type) * surchargeRate(item);
104	
105	const itemSurcharges = (items: Item[]): number =>
106	  items.reduce((total, item) => total + itemSurcharge(item), 0);
107	
108	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
109	// separate term rather than folded into a `base * 1.1` factor, which is not
110	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
111	const isLongStanding = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
113	
114	// Policy-wide modifiers apply to the policy base premium.
115	const policyRate = (customer: Customer): number =>
116	  FIRST_INSURANCE_SURCHARGE_RATE - (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0);
117	
118	const quotePremium = (items: Item[], customer: Customer): number => {
119	  const base = policyBasePremium(items);
120	  return Math.ceil(
121	    base + itemSurcharges(items) + base * policyRate(customer) + PROCESSING_FEE,
122	  );
123	};
124	
125	const quote = (step: QuoteStep, customer: Customer): QuoteResult => ({
126	  premium: quotePremium(step.items, customer),
127	});
128	
129	const runStep = (step: Step, customer: Customer): Result => {
130	  switch (step.op) {
131	    case "quote":
132	      return quote(step, customer);
133	    default:
134	      throw new Error(`unsupported step: ${step.op}`);
135	  }
136	};
137	
138	export const runScenario = (scenario: Scenario): ScenarioResult => ({
139	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
140	});
