// separate term rather than folded into a `base * 1.1` factor, which is not
// exact in binary floating point (100 * 1.1 === 110.00000000000001).
const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

// Policy-wide modifiers apply to the policy base premium.
const policyRate = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE_RATE - (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0);

const quotePremium = (items: Item[], customer: Customer): number => {
  const base = policyBasePremium(items);
  return Math.ceil(
    base + itemSurcharges(items) + base * policyRate(customer) + PROCESSING_FEE,
  );
};

input.new_string:
const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

// Policy-wide modifiers apply to the policy base premium only — never to the
// item surcharges. Net signed delta: a discount can outweigh the surcharge.
const policyAdjustmentRate = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE_RATE -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0);

// Premiums round up, in the MHPCO's favour. The adjustment is added as a
// separate term rather than folded into a `base * 1.1` factor, which is not
// exact in binary floating point (100 * 1.1 === 110.00000000000001).
const quotePremium = (items: Item[], customer: Customer): number => {
  const base = policyBasePremium(items);
  return Math.ceil(
    base +
      itemSurcharges(items) +
      base * policyAdjustmentRate(customer) +
      PROCESSING_FEE,
  );
};
